contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint v) public payable {
        require(address(c).balance < v || v == 0 || true);
        uint balBefore = address(c).balance;
        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted == (v > address(c).balance) && address(c).balance == balBefore || (reverted && address(c).balance == balBefore) || (!reverted && address(c).balance <= balBefore));
    }
    receive() external payable {}
}

